style.css:
@-moz-document domain("autohotkey.com") {
* {
   font-family: imWritingQuat nerd font !important;
	border: 0 !important;
	font-weight: normal !important;
}

.inputbox,
.panel,
html, 
body,
.bg2,
.codebox,
.codebox code,
.section-posting .bg3.panel,
#message-box textarea,
.forabg ul.topiclist li.row, .forumbg ul.topiclist li.row {
    background-color: #191919;
    border-color: #191919;
    
}

.bg1 {
    background-color: #1d1c1c;
}

.wrap {
    max-width: 98%;
    min-width: 98%;
	 background-color: #191919;
    border-color: #191919;
    color: #191919;
}

blockquote cite {
    color: #6A71D2 !important;
}

.inline_code {
    font-family: Maple mono !important;
    color: #ff7df4;
    background: #281c28;
    overflow: visible;
    display: inline-block;
    border-radius: 6px;
}

.codebox code {
    background-color: #191919;
    background-image: none;
}
kbd {
	 font-family: Maple mono !important;
    border: 0px;
    border-radius: 3px;
    box-shadow: none;
    color: #fac84d;
    background-color: #312b26;
    text-shadow: none;
    white-space: nowrap;
}

code {
    border-radius: 3px;
}

.forum_unread .forumtitle, .forum_unread_locked .forumtitle, .forum_unread_subforum .forumtitle,
.icon_topic_newest + a.forumtitle, .icon_topic_newest + a.topictitle, .pm_read .topictitle, a.subforum.unread,
.global_unread .topictitle, .global_unread_mine .topictitle, .announce_unread_mine .topictitle, .announce_unread .topictitle, .global_unread_mine .topictitle, .announce_unread_mine .topictitle, .global_unread_locked .topictitle, .global_unread_locked_mine .topictitle, .announce_unread_locked_mine .topictitle, .announce_unread_locked .topictitle, .global_unread_locked_mine .topictitle, .announce_unread_locked_mine .topictitle, .announce_unread .topictitle, .announce_unread_mine .topictitle, .announce_unread_locked .topictitle, .announce_unread_locked_mine .topictitle, .sticky_unread .topictitle, .sticky_unread_mine .topictitle, .sticky_unread_locked .topictitle, .sticky_unread_locked_mine .topictitle, .topic_unread .topictitle, .sticky_unread .topictitle, .pm_unread .topictitle, .topic_unread_mine .topictitle, .sticky_unread_mine .topictitle, .topic_unread_locked .topictitle, .sticky_unread_locked .topictitle, .topic_unread_locked_mine .topictitle, .sticky_unread_locked_mine .topictitle, .topic_unread_hot .topictitle, .topic_unread_hot_mine .topictitle {
    color: #ffa433;
}

#left .input input.match,
.Syntax,
.button,
.search-box,
.search-box .inputbox,
a.button1, 
a.button2, 
input.button1,
input.button3,
input.button2,
.tabs .tab > a,
blockquote {
    background-color: #2b2b2b;
    color: #333333;
	 border-radius: 6px;
}

.username-coloured,
.mention {
	color: #FF7C20 !important;	
}

bg1 {
    background-color: #191919;
    color: #A968F6;
    background-image: none;
}

.postprofile a, 
.postprofile dt.author a,
p.author {
	color: #A968F6 !important;	
}

.postprofile strong {
	color: #8d8a8a;
}

.postbody h3 {
    font-size: 1em;
	color: #8d8a8a !important;
}

button, input, optgroup, select {
    color: inherit;
    font: inherit;
    margin: 0;
    border-radius: 6px;
}

ul.linklist {
    padding: 0;
    list-style-type: none;
}

#message-box {
    width: 100%;
}

.smiley-box,
.copyright,
.headerbar,
.online-ribbon,
#smiley-box {
    display: none;
}


.postprofile {
    width: 160px !important;
    font-size: 11px !important;
    line-height: 1px !important;
    margin: 0;
    /* min-height: 80px; */
    border: 1px solid transparent;
    border-width: 0 0 0 1px;
    width: 22%;
    float: right;
    display: inline;
}

.postbody {
    width: calc(100% - 120px - 1px - 16px);
    margin-right: 0;
}

.code,
.codebox,
.highlight {
	font-family: Maple mono !important;
}

pre.origin em, code em,
.highlight .cmt {
	font-family: Maple mono !important;
    color: #828282;
}

.highlight>.dec, .highlight>.cfs, .highlight>.dir {
	font-family: Maple mono !important;
    color: #f892ef;
}

.highlight>.biv {
	font-family: Maple mono !important;
    color: #92f8a2;
}

.highlight .str>.esc {
	font-family: Maple mono !important;
    color: #F73A6B;
}

.highlight>.opr, .highlight>.opt, .Syntax span.optional:before, .Syntax span.optional:after {
	font-family: Maple mono !important;
    color: #e72265d9;
}

.highlight>.str {
	font-family: Maple mono !important;
    color: #48e048;
}

.highlight>.num {
	font-family: Maple mono !important;
    color: #98aff9;
}

.Syntax span.func,
.highlight span>a,
.highlight>.cmd, .highlight>.fun {
    color: #70a5eb;
	font-family: Maple mono !important;
}

.highlight>.lab {
	color: #6DBBE6;
	font-family: Maple mono !important;
}

.highlight>.met {
    color: #2200FFD6;
	font-family: Maple mono !important;
}

.highlight>.hot {
	font-family: Maple mono !important;
	color: #FEF324;
}

.highlight>.prp {
	color: #fac84d;
	font-family: Maple mono !important;
}
}
